items = _items
rows = []


def text(value):
    if value is None or value == "":
        return "Not reported"

    if isinstance(value, list):
        return "; ".join(str(x) for x in value)

    return str(value)


def normalize_doi(value):
    value = str(value or "").strip().lower()

    value = value.replace("https://doi.org/", "")
    value = value.replace("http://doi.org/", "")
    value = value.replace("doi:", "")

    return value.strip()


def normalize_text(value):
    value = str(value or "").strip().lower()

    # Normalize repeated spaces without using re
    value = " ".join(value.split())

    # Remove common punctuation
    chars_to_remove = [",", ":", ";", "'", '"', "(", ")", "[", "]", "{", "}"]

    for ch in chars_to_remove:
        value = value.replace(ch, "")

    return value.strip()


for item in items:

    o = item["json"].get("output", {})

    paper_title = text(o.get("paper_title"))
    year = text(o.get("year"))
    doi = text(o.get("doi"))

    # Key parameters
    parameters = []

    # Use new compact field if available
    if o.get("key_parameters"):
        key_parameters = text(o.get("key_parameters"))

    else:
        for p in o.get("input_parameters", []):

            name = p.get("parameter", "Not reported")
            value = p.get("value", "Not reported")
            unit = p.get("unit", "")
            condition = p.get("condition", "")

            entry = f"{name}: {value}"

            if unit and unit != "Not reported":
                entry += f" {unit}"

            if condition and condition != "Not reported":
                entry += f" ({condition})"

            parameters.append(entry)

        key_parameters = (
            "; ".join(parameters)
            if parameters
            else "Not reported"
        )

    # Key metrics
    metrics = []

    if o.get("key_metrics"):
        key_metrics = text(o.get("key_metrics"))

    else:
        for p in o.get("output_metrics", []):

            name = p.get("metric", "Not reported")
            value = p.get("value", "Not reported")
            unit = p.get("unit", "")
            condition = p.get("condition", "")

            entry = f"{name}: {value}"

            if unit and unit != "Not reported":
                entry += f" {unit}"

            if condition and condition != "Not reported":
                entry += f" ({condition})"

            metrics.append(entry)

        key_metrics = (
            "; ".join(metrics)
            if metrics
            else "Not reported"
        )

    # Best results
    results = []

    if o.get("best_results"):
        best_results = text(o.get("best_results"))

    else:
        for p in o.get("comparative_results", []):

            metric = p.get("metric", "Not reported")
            value = p.get("value", "Not reported")
            unit = p.get("unit", "")
            method = p.get("method", "")

            entry = f"{metric}: {value}"

            if unit and unit != "Not reported":
                entry += f" {unit}"

            if method and method != "Not reported":
                entry += f" ({method})"

            results.append(entry)

        best_results = (
            "; ".join(results)
            if results
            else "Not reported"
        )

    # Unique key
    normalized_doi = normalize_doi(doi)

    if normalized_doi and normalized_doi != "not reported":
        unique_key = normalized_doi
    else:
        title_key = normalize_text(paper_title)
        year_key = normalize_text(year)
        unique_key = f"{title_key}|{year_key}"

    # One row per paper
    rows.append({
        "json": {
            "paper_title": paper_title,
            "year": year,
            "doi": doi,
            "research_domain": text(o.get("research_domain")),
            "methods_models": text(
                o.get("methods_models", o.get("methodology"))
            ),
            "key_parameters": key_parameters,
            "key_metrics": key_metrics,
            "best_results": best_results,
            "tools_dataset": text(o.get("tools_dataset")),
            "limitations": text(o.get("limitations")),
            "research_gap": text(o.get("research_gap")),
            "unique_key": unique_key
        }
    })


return rows
